from flask import jsonify


class APIError(Exception):
    def __init__(self, message, status_code=400, payload=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.payload = payload

    def to_dict(self):
        body = dict(self.payload or ())
        body["error"] = self.message
        return body


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(err):
        return jsonify(err.to_dict()), err.status_code

    @app.errorhandler(404)
    def handle_404(err):
        return jsonify({"error": "Resource not found"}), 404

    @app.errorhandler(405)
    def handle_405(err):
        return jsonify({"error": "Method not allowed"}), 405

    @app.errorhandler(500)
    def handle_500(err):
        return jsonify({"error": "Internal server error"}), 500

from datetime import datetime

from flask import request

from app.errors import APIError


def paginate_args():
    try:
        page = int(request.args.get("page", 1))
        per_page = int(request.args.get("per_page", 10))
    except (TypeError, ValueError):
        raise APIError("page and per_page must be integers", 400)

    if page < 1:
        raise APIError("page must be >= 1", 400)
    if per_page < 1 or per_page > 100:
        raise APIError("per_page must be between 1 and 100", 400)

    return page, per_page


def paginated_response(query, page, per_page, serialize=lambda item: item.to_dict()):
    pagination = query.paginate(page=page, per_page=per_page, error_out=False)
    return {
        "items": [serialize(item) for item in pagination.items],
        "page": pagination.page,
        "per_page": pagination.per_page,
        "total": pagination.total,
        "total_pages": pagination.pages,
        "has_next": pagination.has_next,
        "has_prev": pagination.has_prev,
    }


def parse_iso_datetime(value, field_name="due_date"):
    if value is None:
        return None
    if isinstance(value, str):
        try:
            normalized = value.replace("Z", "+00:00")
            return datetime.fromisoformat(normalized)
        except ValueError:
            raise APIError(f"{field_name} must be a valid ISO 8601 datetime", 400)
    raise APIError(f"{field_name} must be a valid ISO 8601 datetime string", 400)


def require_fields(data, fields):
    if not isinstance(data, dict):
        raise APIError("Request body must be a JSON object", 400)
    missing = [f for f in fields if not data.get(f)]
    if missing:
        raise APIError(f"Missing required field(s): {', '.join(missing)}", 400)

from flask import Flask, jsonify

from config import config_by_name


def create_app(config_name="development"):
    app = Flask(__name__)
    app.config.from_object(config_by_name[config_name])

    from app.extensions import db, jwt, migrate

    db.init_app(app)
    jwt.init_app(app)
    migrate.init_app(app, db)

    from app.errors import register_error_handlers

    register_error_handlers(app)

    from app.auth.routes import auth_bp
    from app.categories.routes import categories_bp
    from app.tasks.routes import tasks_bp
    from app.users.routes import users_bp

    app.register_blueprint(auth_bp, url_prefix="/api/auth")
    app.register_blueprint(categories_bp, url_prefix="/api/categories")
    app.register_blueprint(tasks_bp, url_prefix="/api/tasks")
    app.register_blueprint(users_bp, url_prefix="/api/users")

    @app.route("/api/health")
    def health():
        return jsonify({"status": "ok"})

    @jwt.unauthorized_loader
    def unauthorized_callback(reason):
        return jsonify({"error": "Missing or invalid authorization token", "detail": reason}), 401

    @jwt.invalid_token_loader
    def invalid_token_callback(reason):
        return jsonify({"error": "Invalid token", "detail": reason}), 422

    @jwt.expired_token_loader
    def expired_token_callback(jwt_header, jwt_payload):
        return jsonify({"error": "Token has expired"}), 401

    @jwt.revoked_token_loader
    def revoked_token_callback(jwt_header, jwt_payload):
        return jsonify({"error": "Token has been revoked"}), 401

    return app

import re

from flask import Blueprint, jsonify, request
from flask_jwt_extended import (
    create_access_token,
    create_refresh_token,
    get_jwt_identity,
    jwt_required,
)

from app.errors import APIError
from app.extensions import db
from app.models import User
from app.utils import require_fields

auth_bp = Blueprint("auth", __name__)

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


@auth_bp.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    require_fields(data, ["username", "email", "password"])

    username = data["username"].strip()
    email = data["email"].strip().lower()
    password = data["password"]

    if len(username) < 3:
        raise APIError("username must be at least 3 characters", 400)
    if not EMAIL_RE.match(email):
        raise APIError("email is not a valid email address", 400)
    if len(password) < 6:
        raise APIError("password must be at least 6 characters", 400)

    if User.query.filter_by(username=username).first():
        raise APIError("username is already taken", 409)
    if User.query.filter_by(email=email).first():
        raise APIError("email is already registered", 409)

    user = User(username=username, email=email)
    user.set_password(password)
    db.session.add(user)
    db.session.commit()

    access_token = create_access_token(identity=str(user.id))
    refresh_token = create_refresh_token(identity=str(user.id))

    return (
        jsonify(
            {
                "user": user.to_dict(),
                "access_token": access_token,
                "refresh_token": refresh_token,
            }
        ),
        201,
    )


@auth_bp.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    require_fields(data, ["password"])

    if not data.get("username") and not data.get("email"):
        raise APIError("username or email is required", 400)

    query = User.query
    if data.get("username"):
        user = query.filter_by(username=data["username"].strip()).first()
    else:
        user = query.filter_by(email=data["email"].strip().lower()).first()

    if not user or not user.check_password(data["password"]):
        raise APIError("Invalid credentials", 401)

    access_token = create_access_token(identity=str(user.id))
    refresh_token = create_refresh_token(identity=str(user.id))

    return jsonify(
        {
            "user": user.to_dict(),
            "access_token": access_token,
            "refresh_token": refresh_token,
        }
    )


@auth_bp.route("/refresh", methods=["POST"])
@jwt_required(refresh=True)
def refresh():
    identity = get_jwt_identity()
    access_token = create_access_token(identity=identity)
    return jsonify({"access_token": access_token})


@auth_bp.route("/me", methods=["GET"])
@jwt_required()
def me():
    identity = get_jwt_identity()
    user = User.query.get(int(identity))
    if not user:
        raise APIError("User not found", 404)
    return jsonify(user.to_dict())

